import json
import shutil
import subprocess
from pathlib import Path

import pytest

ROOT = Path(__file__).resolve().parent.parent
FIXTURES = ROOT / "tests" / "fixtures" / "videos"


@pytest.fixture(scope="session")
def tiny_video(tmp_path_factory) -> Path:
    """A 3 s 640x360 test clip with audio, generated by ffmpeg (no espeak needed)."""
    if not shutil.which("ffmpeg"):
        pytest.skip("ffmpeg not installed")
    out = tmp_path_factory.mktemp("media") / "tiny.mp4"
    subprocess.run(
        ["ffmpeg", "-v", "error", "-y",
         "-f", "lavfi", "-i", "testsrc=size=640x360:rate=25:duration=3",
         "-f", "lavfi", "-i", "sine=frequency=440:duration=3",
         "-c:v", "libx264", "-pix_fmt", "yuv420p", "-c:a", "aac", "-shortest", str(out)],
        check=True,
    )
    return out


@pytest.fixture(scope="session")
def manifest() -> dict:
    path = FIXTURES / "manifest.json"
    if not path.is_file():
        pytest.skip("fixtures missing; run python3 scripts/make_test_videos.py")
    return json.loads(path.read_text(encoding="utf-8"))
